def eulerian_num(n, m):
    if n == 0:
        return 1
    if m == 0 or m == n:
        return 0
    if m == 1 or m == n - 1:
        return n
    if m == 2 or m == n - 2:
        return n * (n - 1)
    # Recursive formula
    res = 0
    for i in range(1, n):
        res += (-1)**(i + 1) * (n - i) * eulerian_num(n - 1, m - 1)
    return res
