def pancake_sort(arr):
    def flip(arr, k):
        return arr[:k][::-1] + arr[k:]
    def sort(arr):
        curr = len(arr)
        while curr > 1:
            max_idx = 0
            for i in range(1, curr):
                if arr[i] > arr[max_idx]:
                    max_idx = i
            if max_idx != curr - 1:
                if max_idx != 0:
                    arr = flip(arr, max_idx + 1)
                arr = flip(arr, curr)
            curr -= 1
        return arr
    return sort(arr)
